def parse_duration(s):
    total = 0
    num = ''
    for char in s:
        if char.isdigit():
            num += char
        elif char in ('h', 'm', 's'):
            if num:
                value = int(num)
                if char == 'h':
                    total += value * 3600
                elif char == 'm':
                    total += value * 60
                elif char == 's':
                    total += value
                num = ''
    return total
